#!/usr/bin/env bun
/**
 * Generates plugins/<name>/src/route-types.d.ts — the per-plugin
 * `FileRoutesByPath` module augmentations that let plugin route modules
 * (`createFileRoute("/path")`) typecheck inside each plugin's own TS
 * program. The host app's apps/web/src/routeTree.gen.ts is the source of
 * truth; this script mirrors the entries for routes whose file lives
 * under plugins/<name>/.
 *
 * Run after route changes (routeTree.gen.ts is regenerated by the
 * TanStack Start vite plugin on dev/build):
 *
 *   bun run gen:route-types
 *
 * Generated files are never hand-edited. CI verifies they are in sync
 * (ci:route-types task).
 */
import { existsSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { join, posix } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const routeTreePath = join(root, "apps/web/src/routeTree.gen.ts");
const pluginsDir = join(root, "plugins");

if (!existsSync(routeTreePath)) {
	console.error(
		`gen-plugin-route-types: ${routeTreePath} not found — run a dev/build ` +
			"pass first so the TanStack Router generator emits it.",
	);
	process.exit(1);
}

const routeTree = readFileSync(routeTreePath, "utf8");

// Route import bindings: `import { Route as XRouteImport } from './…'`.
// Map binding name -> repo-relative route file path (no extension).
const importRe = /import \{ Route as (\w+) \} from '([^']+)'/g;
const routeFileByBinding = new Map();
for (const m of routeTree.matchAll(importRe)) {
	const [, binding, spec] = m;
	const resolved = posix.normalize(posix.join("apps/web/src", spec));
	routeFileByBinding.set(binding, resolved);
}

// FileRoutesByPath entries (multi-line object literals only — the
// single-line FileRoutesById/FileRoutesByFullPath maps don't match).
const entryRe =
	/'([^'\n]+)':\s*\{\s*\n\s*id:\s*'([^'\n]*)'\s*\n\s*path:\s*'([^'\n]*)'\s*\n\s*fullPath:\s*'([^'\n]*)'\s*\n\s*preLoaderRoute:\s*typeof\s+(\w+)/g;

// plugin name -> (route key -> entry)
const byPlugin = new Map();
let matched = 0;
for (const m of routeTree.matchAll(entryRe)) {
	const [, key, id, path, fullPath, binding] = m;
	const file = routeFileByBinding.get(binding);
	const plugin = file?.match(/(?:^|\/)plugins\/([^/]+)\//)?.[1];
	if (!plugin) continue;
	matched++;
	let entries = byPlugin.get(plugin);
	if (!entries) {
		entries = new Map();
		byPlugin.set(plugin, entries);
	}
	entries.set(key, { id, path, fullPath });
}

if (matched === 0) {
	console.error(
		"gen-plugin-route-types: no plugin route entries found in " +
			"routeTree.gen.ts — the file format may have changed.",
	);
	process.exit(1);
}

// Union with plugins that already have a generated file, so stale files
// for plugins whose routes were all removed get cleaned up.
const existing = new Set();
for (const name of readdirSync(pluginsDir)) {
	if (existsSync(join(pluginsDir, name, "src", "route-types.d.ts"))) {
		existing.add(name);
	}
}
for (const name of byPlugin.keys()) existing.add(name);

// A plugin needs the `import type {} from "@tanstack/react-start"`
// side-effect import when any of its route modules uses the `server`
// route option (api/SSE handlers) — that option's types come from
// @tanstack/start-client-core's module augmentation.
function pluginNeedsServerImport(files) {
	for (const file of files) {
		for (const ext of [".ts", ".tsx"]) {
			const p = join(root, file + ext);
			if (existsSync(p) && /\bserver\s*:/.test(readFileSync(p, "utf8"))) {
				return true;
			}
		}
	}
	return false;
}

// Route keys sorted like the TanStack Router generator's own ordering:
// segment-wise, with static segments before `$param`/`$` segments.
function compareRouteKeys(a, b) {
	const as = a.split("/");
	const bs = b.split("/");
	for (let i = 0; i < Math.min(as.length, bs.length); i++) {
		const x = as[i];
		const y = bs[i];
		if (x === y) continue;
		const xp = x.startsWith("$");
		const yp = y.startsWith("$");
		if (xp !== yp) return xp ? 1 : -1;
		return x < y ? -1 : 1;
	}
	return as.length - bs.length;
}

let written = 0;
let removed = 0;
const summary = [];

for (const plugin of [...existing].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
	const entries = byPlugin.get(plugin);
	const outPath = join(pluginsDir, plugin, "src", "route-types.d.ts");

	if (!entries || entries.size === 0) {
		if (existsSync(outPath)) {
			rmSync(outPath);
			removed++;
			summary.push(`removed ${plugin}/src/route-types.d.ts (no routes)`);
		}
		continue;
	}

	const keys = [...entries.keys()].sort(compareRouteKeys);
	const pluginFiles = [...routeFileByBinding.values()].filter((f) =>
		f.startsWith(`plugins/${plugin}/`),
	);
	const needsServer = pluginNeedsServerImport(pluginFiles);

	const lines = ['import type { AnyRoute } from "@tanstack/react-router";'];
	if (needsServer) {
		lines.push(
			"// Pulls in @tanstack/start-client-core's `declare module` augmentation",
			"// that adds the `server` route option (api handlers) to",
			"// FilebaseRouteOptionsInterface — type-only, no runtime import.",
			'import type {} from "@tanstack/react-start";',
		);
	}
	lines.push(
		"",
		"// This file is generated by tools/gen-plugin-route-types.mjs from",
		"// apps/web/src/routeTree.gen.ts — do not edit it by hand; run",
		"// `bun run gen:route-types` after route changes.",
		"//",
		"// Route modules under this package's src/routes/** and",
		"// src/api-routes/** are typechecked inside the host app's TS",
		"// program, where apps/web/src/routeTree.gen.ts augments",
		"// FileRoutesByPath with the full route tree. This package's own",
		"// program does not see that augmentation, so createFileRoute path",
		"// literals would not resolve. These entries mirror the generated",
		"// ones for the routes this plugin owns; routeTree.gen.ts remains",
		"// the source of truth at runtime.",
		"",
		'declare module "@tanstack/react-router" {',
		"\tinterface FileRoutesByPath {",
	);

	for (const key of keys) {
		const e = entries.get(key);
		lines.push(
			`\t\t"${key}": {`,
			`\t\t\tid: "${e.id}";`,
			`\t\t\tpath: "${e.path}";`,
			`\t\t\tfullPath: "${e.fullPath}";`,
			"\t\t\tpreLoaderRoute: AnyRoute;",
			"\t\t\tparentRoute: AnyRoute;",
			"\t\t};",
		);
	}
	lines.push("\t}", "}", "");

	const content = lines.join("\n");
	const existingContent = existsSync(outPath) ? readFileSync(outPath, "utf8") : null;
	if (existingContent !== content) {
		writeFileSync(outPath, content);
	}
	written++;
	summary.push(
		`${plugin}: ${keys.length} route entr${keys.length === 1 ? "y" : "ies"}` +
			(needsServer ? " (+ react-start import)" : ""),
	);
}

for (const line of summary) console.log(line);
console.log(`gen-plugin-route-types: ${written} file(s) written, ${removed} removed`);
